import { defineCollection } from 'astro:content';
import { z } from 'astro/zod';
import { glob } from 'astro/loaders';
import { languages } from '../handbook.config.ts';

const lang = z.enum(languages);

const book = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/book' }),
  schema: z.object({
    title: z.string(),
    lang,
    // Render variant for the book page. Cover/title/contents sheets are
    // print-only or virtual (generated by the download builders from
    // works.json) and have no MDX source file, so only web variants are
    // valid here. Chapters are full articles; sections are generic
    // front-matter pages (e.g. about) whose heading lives in the MDX body.
    // (Named "template": Astro reserves frontmatter `layout` for MDX layouts.)
    template: z
      .enum(['chapter', 'section'])
      .default('chapter'),
  }),
});

const pages = defineCollection({
  loader: glob({ pattern: '**/*.mdx', base: './src/content/pages' }),
  schema: z.object({
    title: z.string(),
    lang,
    template: z.enum(['home', 'page', 'search']).default('page'),
    openerImage: z.string().optional(),
    openerImageAlt: z.string().optional(),
    openerImageCaption: z.string().optional(),
  }),
});

// One authored brand guide, including live component examples and guidelines.
const brand = defineCollection({
  loader: glob({ pattern: 'brand-guide.mdx', base: './design' }),
  schema: z.object({
    title: z.string(),
    lang: lang.default('en'),
  }),
});

export const collections = { book, pages, brand };
